// Линейный поиск со счётчиком проверок
const data = [7, 3, 9, 1, 8, 2];

function linearSearch(arr, target) {
  let checks = 0;
  for (let i = 0; i < arr.length; i++) {
    checks = checks + 1;
    if (arr[i] === target) {
      return { index: i, checks: checks };
    }
  }
  return { index: -1, checks: checks };
}

const first = linearSearch(data, 8);
const second = linearSearch(data, 5);

console.log('find 8 -> index:', first.index, 'checks:', first.checks);
console.log('find 5 -> index:', second.index, 'checks:', second.checks);

