// Бинарный поиск против линейного: счётчик проверок
const sorted = [2, 5, 8, 11, 14, 17, 20, 23, 26, 29];

function linearChecks(arr, target) {
  let checks = 0;
  for (const item of arr) {
    checks = checks + 1;
    if (item === target) {
      return checks;
    }
  }
  return checks;
}

function binaryChecks(arr, target) {
  let low = 0;
  let high = arr.length - 1;
  let checks = 0;
  while (low <= high) {
    checks = checks + 1;
    const mid = Math.floor((low + high) / 2);
    if (arr[mid] === target) {
      return checks;
    }
    if (arr[mid] < target) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return checks;
}

console.log('target 23 | linear:', linearChecks(sorted, 23), 'binary:', binaryChecks(sorted, 23));
console.log('target 2  | linear:', linearChecks(sorted, 2), 'binary:', binaryChecks(sorted, 2));
console.log('missing 30 | binary:', binaryChecks(sorted, 30));

