// Сортировка выбором и встроенная sort с компаратором
function selectionSort(arr) {
  const a = arr.slice();
  for (let i = 0; i < a.length - 1; i++) {
    let min = i;
    for (let j = i + 1; j < a.length; j++) {
      if (a[j] < a[min]) {
        min = j;
      }
    }
    [a[i], a[min]] = [a[min], a[i]];
  }
  return a;
}

const numbers = [40, 10, 30, 20];
console.log('selection sort:', selectionSort(numbers).join(' '));
console.log('original intact:', numbers.join(' '));

const words = ['pear', 'apple', 'fig'];
console.log('alphabetical:', [...words].sort().join(','));
console.log('by length:', [...words].sort((a, b) => a.length - b.length).join(','));
console.log('default sort:', [5, 40, 200, 30].sort().join(','));
console.log('numeric sort:', [5, 40, 200, 30].sort((a, b) => a - b).join(','));

