// Рекурсия: базовый случай и вызов самой себя
function factorial(n) {
  if (n <= 1) {
    return 1;
  }
  return n * factorial(n - 1);
}

function digitSum(n) {
  if (n < 10) {
    return n;
  }
  return (n % 10) + digitSum(Math.floor(n / 10));
}

function halvingSteps(n) {
  if (n === 1) {
    return 0;
  }
  return 1 + halvingSteps(n / 2);
}

console.log('factorial(5) =', factorial(5));
console.log('digitSum(493) =', digitSum(493));
console.log('halvingSteps(16) =', halvingSteps(16));

