  let second = null;
  for (let i = 1; i < list.length; i++) {
    const x = list[i];
    if (x > best) { second = best; best = x; }
    else if (x < best && (second === null || x > second)) { second = x; }
  }
  return second;
}
6. Санҷиш. Дар [4, 9, 2, 7, 9] мегузаронам: best = 4; 9 > 4 → second = 4, best = 9; 2 < 9 ва 2 < 4 → гузашт; 7 < 9 ва 7 > 4 → second = 7; 9-и дуюм на аз best калон ва на хурд — партофта шуд; ҷавоб 7, бо мисол мувофиқ. [3, 3, 3]: сеҳо ба best баробар ва хурд нестанд — second null мемонад. [1, 2]: best = 1, баъд 2 > 1 → second = 1, best = 2, ҷавоб 1. Ҳамаи мисолҳо мувофиқ омаданд — вазифа ҳал шуд.

referenceAnswer.en:
1. Restating the task. Given a list of numbers. Find the second largest distinct value: if the maximum appears several times, it still counts as one number. If there are fewer than two distinct values, there is no answer — return null.
2. Examples. [4, 9, 2, 7, 9] → maximum 9, second 7. [3, 3, 3] → all equal, no second, null. [1, 2] → maximum 2, second 1. A one-element list → no answer.
3. Simple case. [1, 2] solves mentally: keep best = 2 and second = 1. Hence the idea: during one pass, remember two numbers — the best and the second.
4. Plan. Start best at the first element, second at null. For every next x: if x > best, demote the old best into second and set best = x; otherwise, if x < best and (second is null or x > second), set second = x. The answer is second, where null means “no second”.
5. Code.
function secondLargest(list) {
  let best = list[0];
  let second = null;
